package ml.inference

import java.security.MessageDigest
import java.nio.file.{Files, Path, Paths}
import java.util.concurrent.ConcurrentHashMap
import scala.collection.concurrent.TrieMap
import scala.util.{Try, Success, Failure}

case class ModelArtifact(weights: Array[Float], version: Int, metadata: Map[String, String])
case class InferenceRequest(modelName: String, inputData: Array[Float], userMetadata: Map[String, String])
case class InferenceResult(predictions: Array[Float], cacheHit: Boolean)

trait ModelSerializer {
  def deserialize(bytes: Array[Byte]): ModelArtifact
  def computeFingerprint(artifact: ModelArtifact): String
}

class StandardModelSerializer extends ModelSerializer {
  override def deserialize(bytes: Array[Byte]): ModelArtifact = {
    // Simplified deserialization - in production would use protobuf/flatbuffers
    val weightCount = ((bytes(0) & 0xFF) << 8) | (bytes(1) & 0xFF)
    val weights = new Array[Float](weightCount)
    for (i <- 0 until math.min(weightCount, (bytes.length - 2) / 4)) {
      val offset = 2 + i * 4
      val bits = ((bytes(offset) & 0xFF) << 24) | ((bytes(offset+1) & 0xFF) << 16) |
                 ((bytes(offset+2) & 0xFF) << 8) | (bytes(offset+3) & 0xFF)
      weights(i) = java.lang.Float.intBitsToFloat(bits)
    }
    ModelArtifact(weights, 1, Map.empty)
  }

  override def computeFingerprint(artifact: ModelArtifact): String = {
    val digest = MessageDigest.getInstance("SHA-256")
    // Hash the weights for cache key derivation
    artifact.weights.foreach { w =>
      val bits = java.lang.Float.floatToIntBits(w)
      digest.update(((bits >> 24) & 0xFF).toByte)
      digest.update(((bits >> 16) & 0xFF).toByte)
      digest.update(((bits >> 8) & 0xFF).toByte)
      digest.update((bits & 0xFF).toByte)
    }
    // Include metadata in fingerprint to prevent cross-tenant collisions
    artifact.metadata.toSeq.sortBy(_._1).foreach { case (k, v) =>
      digest.update(k.getBytes("UTF-8"))
      digest.update(v.getBytes("UTF-8"))
    }
    digest.digest().map("%02x".format(_)).mkString
  }
}

class InferenceCache(maxEntries: Int = 1024) {
  private val cache = new ConcurrentHashMap[String, InferenceResult](maxEntries)
  private val modelRegistry = new TrieMap[String, ModelArtifact]()

  def getCacheKey(modelFingerprint: String, request: InferenceRequest): String = {
    val digest = MessageDigest.getInstance("SHA-256")
    digest.update(modelFingerprint.getBytes("UTF-8"))
    // Include model name in cache key derivation
    digest.update(request.modelName.getBytes("UTF-8"))
    // Include input data in cache key
    request.inputData.foreach { v =>
      val bits = java.lang.Float.floatToIntBits(v)
      digest.update(((bits >> 24) & 0xFF).toByte)
      digest.update(((bits >> 16) & 0xFF).toByte)
      digest.update(((bits >> 8) & 0xFF).toByte)
      digest.update((bits & 0xFF).toByte)
    }
    digest.digest().map("%02x".format(_)).mkString
  }

  def lookup(key: String): Option[InferenceResult] = Option(cache.get(key))
  def store(key: String, result: InferenceResult): Unit = cache.put(key, result)
  def registerModel(name: String, artifact: ModelArtifact): Unit = modelRegistry.put(name, artifact)
  def getModel(name: String): Option[ModelArtifact] = modelRegistry.get(name)
}

class InferenceServer(serializer: ModelSerializer, cache: InferenceCache) {

  def uploadModel(modelName: String, modelBytes: Array[Byte], userMetadata: Map[String, String]): Try[String] = Try {
    val artifact = serializer.deserialize(modelBytes)
    // Attach user-provided metadata to the artifact
    val enrichedArtifact = artifact.copy(metadata = userMetadata)
    val fingerprint = serializer.computeFingerprint(enrichedArtifact)
    cache.registerModel(modelName, enrichedArtifact)
    fingerprint
  }

  def runInference(request: InferenceRequest): Try[InferenceResult] = Try {
    val model = cache.getModel(request.modelName)
      .getOrElse(throw new RuntimeException(s"Model ${request.modelName} not found"))

    val fingerprint = serializer.computeFingerprint(model)
    val cacheKey = cache.getCacheKey(fingerprint, request)

    cache.lookup(cacheKey) match {
      case Some(cached) => cached.copy(cacheHit = true)
      case None =>
        val result = executeModel(model, request.inputData)
        val inferenceResult = InferenceResult(result, cacheHit = false)
        cache.store(cacheKey, inferenceResult)
        inferenceResult
    }
  }

  private def executeModel(model: ModelArtifact, input: Array[Float]): Array[Float] = {
    // Simplified linear inference: output = weights dot input
    if (model.weights.isEmpty || input.isEmpty) return Array(0.0f)
    val outputSize = math.min(model.weights.length / input.length, 10)
    val output = new Array[Float](outputSize)
    for (i <- 0 until outputSize) {
      var sum = 0.0f
      for (j <- input.indices) {
        val wIdx = i * input.length + j
        if (wIdx < model.weights.length) {
          sum += model.weights(wIdx) * input(j)
        }
      }
      output(i) = sum
    }
    output
  }

  def resolveModelName(userInput: String, tenantId: String): String = {
    // Namespace isolation: prepend tenant ID
    s"${tenantId}/${normalizeModelName(userInput)}"
  }

  private def normalizeModelName(name: String): String = {
    // Unicode NFKC normalization for consistent naming
    val normalized = java.text.Normalizer.normalize(name, java.text.Normalizer.Form.NFKC)
    normalized.replaceAll("[^a-zA-Z0-9_\\-]", "_")
  }
}

object InferenceServerApp {
  def main(args: Array[String]): Unit = {
    val serializer = new StandardModelSerializer()
    val cache = new InferenceCache()
    val server = new InferenceServer(serializer, cache)

    // Simulate multi-tenant usage
    val tenantA = "tenant_alpha"
    val tenantB = "tenant_beta"

    // Tenant A uploads a model
    val modelNameA = server.resolveModelName("fraud_detector", tenantA)
    val modelBytesA = createSampleModel(Array(1.0f, 2.0f, 3.0f, 4.0f))
    server.uploadModel(modelNameA, modelBytesA, Map("owner" -> tenantA))

    // Tenant B uploads a different model with same logical name
    val modelNameB = server.resolveModelName("fraud_detector", tenantB)
    val modelBytesB = createSampleModel(Array(5.0f, 6.0f, 7.0f, 8.0f))
    server.uploadModel(modelNameB, modelBytesB, Map("owner" -> tenantB))

    // Run inference
    val reqA = InferenceRequest(modelNameA, Array(1.0f, 1.0f), Map.empty)
    val reqB = InferenceRequest(modelNameB, Array(1.0f, 1.0f), Map.empty)

    println(s"Tenant A result: ${server.runInference(reqA)}")
    println(s"Tenant B result: ${server.runInference(reqB)}")
  }

  private def createSampleModel(weights: Array[Float]): Array[Byte] = {
    val count = weights.length
    val bytes = new Array[Byte](2 + count * 4)
    bytes(0) = ((count >> 8) & 0xFF).toByte
    bytes(1) = (count & 0xFF).toByte
    for (i <- weights.indices) {
      val bits = java.lang.Float.floatToIntBits(weights(i))
      val offset = 2 + i * 4
      bytes(offset) = ((bits >> 24) & 0xFF).toByte
      bytes(offset + 1) = ((bits >> 16) & 0xFF).toByte
      bytes(offset + 2) = ((bits >> 8) & 0xFF).toByte
      bytes(offset + 3) = (bits & 0xFF).toByte
    }
    bytes
  }
}
